$ErrorActionPreference="Stop"; $Repo="C:\stock-bot"; $Port=8766; $Python="$Repo\.venv\Scripts\python.exe"; Set-Location $Repo
$old=@(Get-NetTCPConnection -LocalPort $Port -State Listen -ErrorAction SilentlyContinue); foreach($L in $old){Stop-Process -Id $L.OwningProcess -Force -ErrorAction SilentlyContinue}; Start-Sleep 2
$P=Start-Process -FilePath $Python -ArgumentList @("$Repo\dashboard\operations_dashboard_v3_2.py","--root","$Repo","--host","127.0.0.1","--port","$Port") -WorkingDirectory $Repo -PassThru; Start-Sleep 5
$S=Invoke-RestMethod "http://127.0.0.1:$Port/api/status"; $R=$S.trade_analytics.cross_ledger_reconstruction; Write-Host "DASHBOARD PID:" $P.Id; Write-Host "NUMERIC TRADES:" $S.trade_analytics.historical.numeric_trade_count; Write-Host "NET REALIZED PNL:" $S.trade_analytics.historical.net_realized_pnl; Write-Host "RECONSTRUCTED TRADES:" $R.reconstructed_trade_count; Write-Host "RECONSTRUCTION STATUS:" $R.status; if($S.trade_analytics_status -like "ISOLATED_*"){throw "DASHBOARD ANALYTICS FAILED"}; Write-Host "DASHBOARD RUNTIME: PASS"
